#!/usr/bin/env python3
"""Attach matching English to each Latin unit and write de-gradibus.json.

Long units are then broken into lectio chunks (praefatio-s1, …) without
changing latin-units.json. See scripts/split_lectio.py.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LATIN = ROOT / "src/content/gradibus/latin-units.json"
OUT = ROOT / "src/content/gradibus/de-gradibus.json"
sys.path.insert(0, str(Path(__file__).parent))
from split_lectio import add_chunks, report  # noqa: E402

EN: dict[str, str] = {
    "title": "Saint Bernard, Abbot of Clairvaux: A Treatise on the Steps of Humility and of Pride.",
    "retractatio": "In this little work, when I brought forward that saying of the Gospel in which the Lord states that He does not know the day of the last judgment, in order to confirm and strengthen a certain opinion (ch. 1, n. 1), I incautiously added a word which I afterwards found is not written in the Gospel. For while the text has only “nor does the Son know,” I, misled rather than wishing to mislead, unmindful of the letter though not of the sense, wrote, “Nor does the Son of Man Himself know.” And from that inaccurate wording I then built the whole of the following argument, trying to prove a true claim from something I had not truly set down. But because I discovered this error of mine long after the booklet had been published by me and already copied by many, and I could not chase a falsehood already scattered through so many copies, I thought it necessary to take refuge in the remedy of confession. In another place also (ch. 10, n. 35) I set down an opinion about the Seraphim which I have never heard and nowhere read. Here my reader should notice that I therefore said, with restraint, “I suppose”: meaning that I wished nothing more than that it be taken as a conjecture, since I could not make it certain from the Scriptures. The title itself, which is inscribed “On the Steps of Humility,” may also meet with censure, perhaps because the steps distinguished and described here seem to be those of pride rather than of humility; but this will come only from those who understand or attend too little to the reason of that title, which I have been careful to indicate briefly at the end of the work.",
    "praefatio": "You asked me, brother Godfrey, to set out more fully, in a treatise for you, those things I had spoken before the brothers concerning the steps of humility. Wishing to satisfy this request of yours as it deserved, and fearing that I could not, and mindful of the Gospel counsel, I confess that I did not dare to begin until I had sat down and counted whether I had resources enough to finish (Luke 14:28). Then, when charity had cast out this fear—the fear of being mocked for a work left unfinished—another fear of the opposite kind came in, and I began to dread a graver danger from glory if I succeeded than from disgrace if I failed. And so, placed as it were at a fork between this fear and charity, I hesitated long as to which road I might safely trust; fearing either that, by speaking usefully of humility, I myself might be found not humble, or that, by keeping a humble silence, I might become useless. And since I saw that neither way was safe, yet that I must take one of them, I chose rather to share with you, if I could, the fruit of the discourse, than to keep myself alone in the harbor of silence: trusting at the same time that if I should happen to say something you approve, I may by your prayers be kept from pride; but if (as I rather think) I produce nothing worthy of your study, I cannot be proud of nothing.",
    "cap1-title": "Chapter I. That Christ is the way of humility by which one comes to the truth.",
    "cap1-s1": "About to speak, then, of the steps of humility, which blessed Benedict sets before us not to be numbered but to be climbed (Rule, ch. 7), I first show, if I can, whither one must come by them, so that when the fruit of arrival is heard, the labor of the ascent may weigh less. So the Lord sets before us the labor of the way and the reward of the labor: “I am,” He says, “the way, the truth, and the life” (John 14:6). He calls the way humility, which leads to the truth. The one is labor, the other the fruit of labor. “How am I to know,” you ask, “that He was speaking there of humility, when He said indefinitely, ‘I am the way’?” Hear more plainly: “Learn from Me, for I am meek and humble of heart” (Matt. 11:29). He therefore sets Himself forth as the example of humility, the pattern of meekness. If you imitate Him, you do not walk in darkness, but you will have the light of life (John 8:12). What is the light of life, if not the truth, which, enlightening every man coming into this world, shows where true life is? Therefore when He had said, “I am the way and the truth,” He added, “and the life”: as if He said, “I am the way, who lead to the truth; I am the truth, who promise life; I am the life, which I give.” “For this,” He says, “is eternal life, that they may know You, the true God, and Jesus Christ whom You have sent.” Or thus, as if you should say: “I consider the way, that is humility; I desire the fruit, the truth. But what if the labor of the way is so great that I cannot reach the hoped-for gain?” He answers: “I am the life,” that is, the provision by which you may be sustained on the way. He therefore cries to those who wander and do not know the way, “I am the way”; to those who doubt and do not believe, “I am the truth”; to those already climbing but growing weary, “I am the life.” Enough, I think, has been shown from the proposed chapter of the Gospel, that the knowledge of the truth is the fruit of humility. Take another saying also. “I confess to You, Father, Lord of heaven and earth, because You have hidden these things”—no doubt the secrets of the truth—“from the wise and prudent,” that is, from the proud, “and have revealed them to little ones” (Luke 10:21), that is, to the humble. And in this it appears that the truth, which is hidden from the proud, is revealed to the humble.",
    "cap1-s2": "Now such may be the definition of humility: Humility is the virtue by which a man, through a most true knowledge of himself, becomes cheap in his own eyes. This belongs to those who, having set ascents in their heart, advance from virtue to virtue, that is from step to step, until they come to the summit of humility, in which, placed as it were in Zion, that is in contemplation, they look upon the truth. For “the lawgiver,” it is said, “will give a blessing” (Ps. 83:8): because He who gave the law will also give the blessing; that is, He who commanded humility will lead through to the truth. And who is this lawgiver, if not the Lord, sweet and upright, who gave a law to those who go astray in the way? (Ps. 24:8.) They go astray in the way who abandon the truth. But are they even so abandoned by the sweet Lord? To them, then, the Lord, sweet and upright, gives as a law the way of humility, by which they may return to the knowledge of the truth. He gives an occasion of recovering salvation, because He is sweet; yet not without the discipline of the law, because He is upright. Sweet, because He does not suffer them to perish; upright, because He does not forget to punish.",
    "cap2-title": "Chapter II. With what fruit the steps of humility are climbed.",
    "cap2-s3": "This law, then, by which one returns to the truth, blessed Benedict arranges in twelve steps: so that as through the ten commandments of the Law and the twofold circumcision (in which the number twelve is completed) one comes to Christ, so when these twelve steps have been climbed, the truth is laid hold of. That also which appeared in that ladder shown to Jacob as a type of humility, the Lord leaning upon it from above (Gen. 28:12–13)—what else does it hint to us, except that the knowledge of the truth is set at the summit of humility? For the Lord looked down from the top of the ladder upon the children of men as Truth, whose eyes as they will not deceive, so they do not know how to be deceived, that He might see if there is one who understands or seeks God. Does He not seem to you to cry from on high and to say to those who seek Him (for He knows who are His): “Come over to Me, all you who desire Me, and be filled from my produce”? (Sir. 24:26) and this: “Come to Me, all you who labor and are heavy laden, and I will refresh you” (Matt. 11:28). “Come,” He says. Whither? To Me, the truth. By what way? Through humility. With what fruit? “I will refresh you.” But what is the refreshment which Truth promises to those who climb and pays to those who arrive? Is it perhaps charity itself? For to this, as blessed Benedict says, the monk will soon come when all the steps of humility have been climbed (Rule, ch. 7, step 12). Truly sweet and pleasant food is charity, which lifts the weary, strengthens the weak, gladdens the sad. In short, it makes the yoke of Truth sweet and its burden light.",
    "cap2-s4": "Good food is charity, which, standing in the middle of Solomon’s litter (Song 3:9–10), by the scent of various virtues, as by the fragrance of spices of different kinds, refreshes the hungry and delights those who are refreshed. For there are set out peace, patience, kindness, long-suffering, joy in the Holy Spirit; and if there are any other fruits of truth or of wisdom, they are served in it. Humility also has its dishes in the same litter: namely the bread of sorrow and the wine of compunction, which Truth first offers to beginners, to whom it is said: “Rise after you have sat, you who eat the bread of sorrow” (Ps. 126:2). Contemplation has there, from the fat of wheat, the solid food of wisdom, with the wine that gladdens the heart of man, to which Truth invites the perfect, saying: “Eat, my friends, and drink; and be inebriated, O dearest” (Song 5:1). “He paved the middle,” it says, “with charity for the daughters of Jerusalem”; that is, for imperfect souls, who, while they still cannot take that solid food, must for a time be nourished with the milk of charity instead of bread, and with oil instead of wine. And it is rightly described as in the middle, because its sweetness is not yet at hand for beginners, fear forbidding it; nor is it enough for the perfect, on account of the more abundant sweetness of contemplation. The former, still to be purged by the most bitter drink of fear from the noxious humors of carnal delights, do not yet taste the sweetness of milk; the latter, already weaned from milk, are more gloriously delighted to feast from the entrance of glory: only those in the middle, that is those making progress, have already tasted certain honeyed sips of charity, so as for the time to be content with them because of their tenderness.",
    "cap2-s5": "The first food, then, is that of humility, purgative with bitterness; the second, of charity, consoling with sweetness; the third, of contemplation, solid with strength. Woe is me, O Lord God of hosts! How long will You be angry against the prayer of Your servant, and feed me with the bread of tears, and give me tears to drink? Who will invite me even to that middle and sweet banquet of charity, where the just feast in the sight of God and delight in gladness, so that I may no longer speak in the bitterness of my soul and say to God, “Do not condemn me,” but, feasting on the unleavened bread of sincerity and truth, may sing gladly in the ways of the Lord, for great is the glory of the Lord? Yet good is the way of humility, by which truth is sought, charity is gained, and the fruits of wisdom are shared. In short, as the end of the law is Christ, so the perfection of humility is the knowledge of the truth. Christ, when He came, brought grace: Truth, to those to whom it becomes known, gives charity. But it becomes known to the humble: therefore it is to the humble that it gives grace.",
    "cap3-title": "Chapter III. In what order the steps of humility lead to the appointed prize of truth; and how Christ learned mercy through His Passion.",
    "cap3-s6": "I have said, as I could, with what fruit the steps of humility ought to be climbed: I will say, as I shall be able, in what order they lead to the appointed prize of truth. But because the knowledge of truth itself also consists in three steps, I distinguish them briefly, if I can, so that it may become clearer to which of the three of truth the twelfth of humility attains. For we seek the truth in ourselves, in our neighbors, and in its own nature. In ourselves, by judging ourselves; in our neighbors, by compassionating their evils; in its own nature, by contemplating with a pure heart. Observe the order as well as the number. First let Truth itself teach you that it ought to be sought in neighbors before it is sought in its own nature. After this you will learn why you ought to seek it in yourself before in your neighbors. For in the number of the Beatitudes, which the Lord distinguished in His sermon, He placed the merciful before the pure in heart (Matt. 5:7–8). The merciful quickly grasp the truth in their neighbors, while they stretch their affections toward them, and so conform themselves to them by charity that they feel their goods or their ills as their own. They are weak with the weak, they burn with those who are scandalized (2 Cor. 11:29). They have been accustomed to rejoice with those who rejoice and to weep with those who weep (Rom. 12:15). With the edge of the heart cleansed by this brotherly charity, they delight to contemplate the truth in its own nature, for love of which they bear the evils of others. But those who do not so associate themselves with their brothers, but on the contrary insult those who weep or belittle those who rejoice—while they do not feel in themselves what is in others, because they are not similarly affected—how can they grasp the truth in their neighbors? The common proverb fits them well: The healthy man does not know what the sick man feels, nor the full man what the hungry man suffers. And the sick man with the sick, and the hungry with the hungry, compassion the more familiarly as they are the nearer. For as pure truth is seen only by a pure heart, so a brother’s misery is more truly felt by a miserable heart. But that you may have a miserable heart because of another’s misery, you must first acknowledge your own, so that you may find your neighbor’s mind in your own, and may know from yourself how to help him: by the example, namely, of our Savior, who willed to suffer that He might know how to compassion, to become wretched that He might learn to have mercy, so that as it is written of Him, “He learned obedience from the things which He suffered” (Heb. 5:8), He might also learn mercy. Not that He who did not know how to have mercy beforehand—He whose mercy is from eternity and unto eternity—but that what He knew by nature from eternity, He learned by a temporal experiment.",
    "cap3-s7": "But perhaps it seems hard to you that I have said that Christ, the Wisdom of God, learned mercy; as if He through whom all things were made had at some time been ignorant of something among the things that are: especially since that passage from the Epistle to the Hebrews which I recalled to prove this can be understood in another sense, which may not seem so absurd; so that this word “He learned” is referred not to the Head Himself in His own person, but to His body, which is the Church; and so the sense would be: “And He learned obedience from the things which He suffered,” that is, He learned obedience in His body from those things which He suffered in the Head. For that death, that cross, the insults, spittings, scourgings, all of which Christ our Head passed through—what else were they to His body, that is to us, than outstanding lessons of obedience? For “Christ,” says Paul, “became obedient to the Father unto death, even the death of the cross” (Phil. 2:8). By what necessity? Let the apostle Peter answer: “Christ suffered for us, leaving you an example, that you should follow,” he says, “His steps” (1 Pet. 2:21), that is, that you should imitate His obedience. From the things, then, which He suffered, we learn how much we, who are mere men, ought to endure for obedience, for which He who was also God did not hesitate to die. And in this way, you say, it will not be unfitting if Christ is said to have learned obedience, or mercy, or anything else in His body: provided only it is not believed that anything which had before been hidden from Him could have accrued to Him in His own person in time. And so He Himself would be the one who teaches how to have mercy or to obey, and Himself the one who learns: because Head and body are one Christ.",
    "cap3-s8": "I do not deny that this understanding is a right one; but from another place in the same Epistle the former interpretation seems to be confirmed, where it is said: “For nowhere does He take hold of angels, but He takes hold of the seed of Abraham: whence He ought to be made like His brothers in all things, that He might become merciful” (Heb. 2:16–17). I think that these words are to be referred to the Head in such a way that they cannot at all be fitted to the body. It is said of the Word of God that He did not take hold of angels, that is, did not assume them into one person with Himself, but the seed of Abraham. For it is not read, “The Word was made an angel,” but “The Word was made flesh” (John 1:14), and flesh from the flesh of Abraham, according to the promise which was first made to him. Whence—that is, from this assumption of the seed—He ought to be made like His brothers in all things; that is, it was fitting and necessary that, passible like us, He should run through all the kinds of our miseries, except sin. If you ask, by what necessity? “That He might become merciful,” it says. And this, you say, why can it not rightly be referred to the body? But hear what follows a little later: “For in that in which He Himself has suffered and been tempted, He is able to help those also who are tempted” (Heb. 2:18). In which words I do not see what can better be understood, except that He therefore willed to suffer and to be tempted, and to share in all human miseries except sin (which is to be made like His brothers in all things), so that He Himself might learn by experience to have mercy and to compassion those similarly suffering and tempted.",
    "cap3-s9": "By this experiment I do not say that He was made wiser, but that He was seen to be nearer: so that the weak sons of Adam, whom He did not disdain to make His own and to call His brothers (Heb. 2:11), might not hesitate to commit their infirmities to Him who could heal them as God, and would as a neighbor, and knew them as one who had suffered the same. Hence Isaiah calls Him a man of sorrows, and knowing infirmity (Isa. 53:3); and the Apostle: “For we have not,” he says, “a High Priest who cannot compassion our infirmities.” And indicating whence He can, he adds: “but one tempted in all things after our likeness, without sin” (Heb. 4:15). For the blessed God, the blessed Son of God, in that form in which He did not think it robbery to be equal with the Father, was beyond doubt impassible, before He emptied Himself taking the form of a servant (Phil. 2:6–7); and as He had not experienced misery or subjection, so He had not known mercy or obedience by experiment. He knew them indeed by nature, but He did not know them by experience. But when He was made lower not only than Himself, but also a little lower than the angels, who themselves are impassible by grace, not by nature, down to that form in which He could suffer and be subjected, which (as has been said) He could not in His own; He experienced mercy in the Passion, and obedience in subjection. Yet by this experience, as I have said, it was not knowledge that grew in Him, but confidence in us, while by this wretched kind of knowing He from whom we had wandered far was made nearer to us. For when would we have dared to draw near to Him remaining in His impassibility? But now, as the Apostle urges, we are admonished to go with confidence to the throne of His grace (Heb. 4:16), whom surely, as it is written elsewhere, we know to have borne our griefs and carried our sorrows (Isa. 53:4), and we do not doubt that He can compassion us in that in which He Himself has suffered.",
    "cap3-s10": "It ought not, then, to seem absurd if it is said that Christ did not indeed begin to know something which He had at some time not known, yet knew mercy in one way from eternity through the Godhead, and learned it in another way in time through the flesh. See whether that also was said in a similar manner of speaking, when the Lord, to the disciples asking about the last day, answered that He did not know it. For how did He not know that day, in whom all the treasures of wisdom and knowledge are hidden? (Col. 2:3.) Why then did He deny that He knew what it is certain He could not not know? Did He perhaps wish deceitfully to hide from them what He could not usefully make known? Far from it. As He could be ignorant of nothing, since He is Wisdom, so He could not lie, since He is Truth. But wishing to restrain the disciples from the curiosity of a useless inquiry, He denied that He knew what they were asking: not altogether, but in a certain manner in which He could truthfully deny it. For although by the gaze of His Godhead, surveying equally all things, past, present, and future, He also had that day openly; yet He had not come to know it by experiencing it with any senses of His flesh. Otherwise He would already have slain Antichrist with the spirit of His mouth; would already have heard with the ears of His body the archangel crying out and the trumpet sounding, at which noise the dead are to be raised; would already have seen with the eyes of His flesh the sheep and the goats who are to be separated from one another.",
    "cap3-s11": "Finally, that you may understand that it was only by that knowledge which comes through the flesh that He declared Himself not to know that day, answering watchfully He does not say, “Nor do I know,” but “nor does the Son of Man Himself know” (Mark 13:32). What is “Son of Man,” if not the name of the assumed flesh? By which name it is given to be understood that, when He says He does not know something, He speaks not according to what He is as God, but according to man. For otherwise, speaking of Himself according to His divinity, He has more often been accustomed to put not “Son,” or “Son of Man,” but “I,” or “Me,” as there: “Amen, amen, I say to you, before Abraham was made, I am” (John 8:58). “I am,” He says: not, “the Son of Man is.” And there is no doubt that He was speaking of that essence by which He is before Abraham and without beginning, not of that by which He was made after Abraham and from Abraham. Elsewhere also, inquiring of the disciples the opinion of men about Himself, “Whom,” He says, “do men say”—not Me, but—“the Son of Man is?” Again asking the same men what they themselves also thought of Him: “But you,” not “whom the Son of Man,” but “whom do you say that I am?” Inquiring, that is, the opinion of a carnal people about the flesh, He put the name of the flesh, which properly is Son of Man; but asking the spiritual disciples about His divinity, He said not “the Son of Man,” but pointedly “Me.” Which Peter at last understanding, showed by his answer what they had been asked by that “Me”: “You are,” he says, not “Jesus the son of the Virgin,” but “Christ the Son of God” (Matt. 16:13–16). Which if he had answered, he would nevertheless have said the truth; but prudently noticing in the words of the question the sense of the questioner, he answered the things asked fitly and properly, saying: “You are the Christ, the Son of God.”",
    "cap3-s12": "Since therefore you see that Christ has two natures in one person, one by which He always was, the other by which He began to be; and according to His eternal being always knew all things, but according to the temporal was experienced in many things in time: why do you hesitate to confess that, as He began to be in time from the flesh, so He also began to know the miseries of the flesh, at least by that mode of knowing which the weakness of the flesh teaches? Which kind of knowledge our first parents would more wisely and more happily have not known, since they could not attain it except foolishly and miserably. But God their Fashioner, seeking what had perished, in mercy followed His own work, Himself descending mercifully to where they had fallen miserably. He willed to experience in Himself what they deservedly suffered by acting against Him, not indeed with a like curiosity, but with marvelous charity: not that He might remain wretched with the wretched, but that, having become merciful, He might free the wretched. Having become, I say, merciful, not with that mercy which, remaining blessed, He had from eternity, but with that which, by the medium of misery, He found in our habit. Further, the work of piety which He began by the former He completed in the latter: not because the former alone could not complete it, but because for us it could not suffice without this latter. Both were necessary; but this was more fitting for us. O unspeakable device of piety! When would we have thought of that wondrous mercy which preceding misery does not shape? When would we have noticed that compassion unknown to us which, not preceded by passion, endures with impassibility? Yet if that mercy which knows no misery had not gone before, He would not have come to this whose mother is misery. If He had not come, He would not have drawn; if He had not drawn, He would not have drawn out. And from where did He draw out, if not from the pit of misery and the mire of dregs? (Ps. 39:3.) Yet He did not abandon that former mercy, but inserted this; He did not change it, but multiplied it, as it is written: “Men and beasts You will save, O Lord: how You have multiplied Your mercy, O God” (Ps. 35:7–8).",
    "cap4-title": "Chapter IV. The first step of truth is first to attend to oneself, or to acknowledge one’s own misery.",
    "cap4-s13": "But let us now return to our purpose. If then He who was not wretched made Himself wretched, that He might experience what He also knew before: how much more should you—I do not say make yourself what you are not, but attend to what you are, because you are truly wretched, and so learn to have mercy, who cannot otherwise know this! Lest perhaps, if you consider your neighbor’s evil and do not attend to your own, you be moved not to pity but to indignation; not to helping, but to judging; finally not to instructing in the spirit of meekness, but to destroying in the spirit of fury. “You who are spiritual,” says the Apostle, “instruct such a one in the spirit of meekness.” It is the Apostle’s counsel, or even command, that you should succor a sick brother with that meek spirit with which you wish to be succored when you are sick. And that you may know how you can grow meek toward one who goes astray, “considering yourself,” he says, “lest you also be tempted” (Gal. 6:1).",
    "cap4-s14": "It is worth considering how well the disciple of Truth follows the order of the Master. In the Beatitudes, which I recalled above (n. 6), as the merciful were named before the pure in heart, so the meek before the merciful (Matt. 5:4, 7, 8). And the Apostle, when he exhorted the spiritual to instruct the carnal, added, “in the spirit of meekness.” For the instruction of the brothers belongs to the merciful; the spirit of meekness, to the meek. As if he said: He cannot be reckoned among the merciful who is not meek in himself. See, the Apostle openly shows what I promised above I would show (n. 6), namely that the truth is first to be sought in us rather than in our neighbors; “considering,” he says, “yourself,” that is, how easy to temptation, how prone to sin: so that from the consideration of yourself you may grow meek, and so come to help others in the spirit of meekness. Otherwise, if you do not hear the disciple warning, fear the Master accusing: “Hypocrite, cast out first the beam from your own eye; and then you will see to cast out the speck from your brother’s eye” (Matt. 7:5). The beam in the eye, great and thick, is pride in the mind: which by a certain bulk of itself, vain not sound, swollen not solid, darkens the eye of the mind and overshadows the truth: so that if it has occupied your mind, you can no longer see yourself, no longer feel yourself such as you are, or such as you can be; but such as you love, such you either think yourself to be, or hope to become. For what else is pride than (as a certain saint defines it) the love of one’s own excellence? Whence we also can say by contrary, that humility is the contempt of one’s own excellence. But love, as hatred also, does not know the judgment of truth. Do you wish to hear the judgment of Truth? “As I hear, so I judge” (John 5:30). Not as I hate, not as I love, not as I fear. There is a judgment of hatred, as that: “We have a law, and according to our law He ought to die” (John 19:7). There is also one of fear, as that: “If we let Him so, the Romans will come and take away our place and nation” (John 11:48). But a judgment of love, as David concerning his parricide son: “Spare,” he says, “the boy Absalom” (2 Sam. 18:5). And I know it is laid down by human laws, and observed in causes both ecclesiastical and secular, that the special friends of the litigants ought not to be admitted to judgment: lest they either deceive or be deceived by love of their own. And if the love of a friend either lessens his fault in your judgment, or wholly hides it: how much more does love of yourself deceive your judgment against yourself!",
    "cap4-s15": "Whoever therefore cares to know the truth fully in himself must, when the beam of pride which keeps the eye from the light has been removed, set ascents in his heart, by which he may seek himself in himself, and so after the twelfth of humility reach the first step of truth. And when, the truth having been found in himself—or rather himself found in the truth—he can say, “I believed, therefore I have spoken; but I was humbled exceedingly”: let a man ascend to a high heart, that the truth may be exalted, and coming to the second step say in his excess: “Every man is a liar” (Ps. 115:10–11). Do you think David did not keep this order? Do you think the Prophet did not feel this, which the Lord, which the Apostle, which we also after them and through them feel? “I believed,” he says, the Truth saying: “He who follows Me does not walk in darkness” (John 8:12). I believed therefore by following, “therefore I have spoken” by confessing. What by confessing? The truth which I came to know by believing. But after I both believed unto justice and spoke unto salvation, “I was humbled exceedingly,” that is, perfectly. For “exceedingly” can be understood as “perfectly”; as there: “He will delight exceedingly in His commandments” (Ps. 111:1). But if anyone contends that “exceedingly” is put here for “greatly,” not for “perfectly,” because the expositors also seem to maintain this: even this does not discord from the Prophet’s sense, so that we may take him to have said: I indeed, while I did not yet know the truth, thought myself to be something, when I was nothing. But after, by believing in Christ, that is by imitating His humility, I came to know the truth, it was indeed exalted in me by my confession: but I was humbled exceedingly, that is, I became very cheap to myself from the consideration of myself.",
    "cap5-title": "Chapter V. The second step of truth is, from the knowledge of one’s own infirmity, to compassion the misery of one’s neighbor.",
    "cap5-s16": "The Prophet, then, humbled in this first step of truth, as he says in another psalm: “And in Your truth You have humbled me” (Ps. 118:75), let him attend to himself, and from his own misery weigh the general; and so passing to the second let him say in his excess, “Every man is a liar.” In what excess of his? In that, surely, in which, exceeding himself and clinging to the truth, he judges himself. In that excess of his, then, let him say, not with indignation or insult, but with pity and compassion: “Every man is a liar.” What is “Every man is a liar”? Every man is weak, every man wretched and powerless, who can save neither himself nor another. As it is said: “A horse is deceitful for salvation” (Ps. 32:17), not that the horse deceives anyone, but because he deceives himself who trusts in its strength: so every man is called a liar, that is fragile, changeable, from whom neither his own salvation nor another’s can be hoped: rather he incurs a curse who puts his hope in man (Jer. 17:5). The humble Prophet, then, advancing under the guidance of truth, and seeing in others what he lamented in himself, while he adds knowledge, let him also add grief, and generally but truly say: “Every man is a liar.”",
    "cap5-s17": "See how far otherwise that proud Pharisee felt about himself. What did he bring out in his excess? “God, I thank You that I am not as the rest of men” (Luke 18:11). While he exults in himself singularly, he arrogantly insults others. But David speaks otherwise. For he says: “Every man is a liar.” He excepts no one, lest he deceive anyone: knowing that all have sinned, and all lack the glory of God (Rom. 3:23). The Pharisee deceives himself alone, whom alone he excepts, while he condemns the rest. The Prophet does not except himself from the common misery, lest he be excepted from mercy: the Pharisee blows away mercy, while he disguises misery. The Prophet affirms as of all, so of himself: “Every man is a liar”: the Pharisee confirms it of all except himself, “I am not,” he says, “as the rest of men.” And he gives thanks, not because he is good, but because he is alone: not so much for the goods he has, as for the evils he sees in others. He had not yet cast the beam out of his own, and he counts the specks in his brothers’ eyes. For he adds: “unjust, extortioners” (Luke 18:11). Not in vain, I think, have I gone aside from the purpose, if you have understood the difference of both excesses.",
    "cap5-s18": "Now we must return to the purpose. Those, then, whom the truth has already made known to themselves, and thereby made cheap, it is necessary that all the things they were accustomed to love, and they themselves to themselves, should grow bitter. Setting themselves before themselves, they compel themselves to see themselves such as they blush to be seen even by themselves. And while what they are displeases them, and they sigh for what they are not, which they wholly distrust they can be by themselves; weeping over themselves vehemently, they find this only consolation, that as severe judges of themselves, who for love of the true hunger and thirst for justice, they exact from themselves a most strict satisfaction even to self-contempt, and amendment for the future. But when they see that they cannot suffice for this (for when they have done all that was commanded them, they say they are unprofitable servants (Luke 17:10)), they flee from justice to mercy. And that they may obtain it, they follow the counsel of Truth: “Blessed are the merciful, for they shall obtain mercy” (Matt. 5:7). And this is the second step of truth, by which they seek it in their neighbors; while from their own they search out the needs of others; while from the things they suffer they know how to compassion those who suffer.",
    "cap6-title": "Chapter VI. The third step of truth: to cleanse the eye of the heart for contemplating heavenly and divine things.",
    "cap6-s19": "If then they persevere in these three things that have been said, that is in the mourning of penitence, in the desire of justice, in the works of mercy, they cleanse the edge of the heart from the three hindrances which they contracted either by ignorance, or by infirmity, or by zeal, so that through contemplation they may pass over to the third step of truth. These are ways that seem good to men, those only excepted who rejoice when they have done evil and exult in the worst things (Prov. 2:14), and cover themselves with infirmity or ignorance to make excuses in sins (Ps. 140:4). But in vain do they flatter themselves with infirmity or ignorance, who, that they may sin more freely, willingly are ignorant or infirm. Do you think it profited the first man, even though he did not sin willingly, that he defended himself through his wife, as through the infirmity of the flesh (Gen. 3:12)? Or will the stoners of the first martyr, because they stopped their ears (Acts 7:56), be excusable through ignorance? Those therefore who feel themselves alienated from the truth by the zeal and love of sinning, pressed by infirmity and ignorance, let them turn zeal into groaning, love into mourning, let them conquer the infirmity of the flesh by the fervor of justice, let them drive out ignorance by generosity: lest if they now ignore the needy, naked, and infirm truth, they come to know her too late, with shame, when she comes with great power and virtue, terrifying and accusing, and answer in vain with trembling: “When did we see You in need, and did not minister to You?” (Matt. 25:44.) The Lord will surely be known when He executes judgments (Ps. 9:17), who is now ignored when He seeks mercy. Finally they shall look on Him whom they pierced (John 19:37): and likewise the avaricious on Him whom they despised. From every stain, then, contracted by infirmity, ignorance, or zeal, by weeping, by hungering for justice, by clinging to works of mercy, the eye of the heart is cleansed, to which Truth promises herself to be seen in her own purity: “Blessed are the pure in heart, for they shall see God” (Matt. 5:8). Since there are three steps or states of truth, we climb to the first by the labor of humility, to the second by the affection of compassion, to the third by the excess of contemplation. In the first, truth is found severe; in the second, kind; in the third, pure. To the first, reason leads, by which we examine ourselves; to the second, affection brings us, by which we pity others; to the third, purity snatches us, by which we are lifted to invisible things.",
    "cap7-title": "Chapter VII. How the Holy Trinity works these three steps of truth in us.",
    "cap7-s20": "Here a certain wondrous and distributed operation of the undivided Trinity shines through to me, if somehow that ineffable distinction of the persons cooperating with one another can be grasped by a man sitting in darkness. In the first step the Son, in the second the Holy Spirit, in the third the Father seems to me to work. Do you wish to hear the operation of the Son? “If I,” He says, “the Lord and Master, have washed your feet, how much more ought you also to wash one another’s feet?” (John 13:14.) The Master of truth was handing to the disciples the form of humility, by which in the first step the truth might first become known to them. Attend also to the work of the Holy Spirit: “The charity of God is poured forth in our hearts by the Holy Spirit who has been given to us” (Rom. 5:5). For charity is the gift of the Holy Spirit, by which it comes about that those who under the discipline of the Son have already advanced through humility as far as the first step of truth, come to the second through compassion of the neighbor, under the teaching of the Holy Spirit. Hear also of the Father: “Blessed are you, Simon Bar-Jona, because flesh and blood has not revealed it to you, but My Father who is in heaven” (Matt. 16:17); and this: “The Father will make His truth known to the children” (Isa. 38:19); and, “I confess to You, Father, because You have hidden these things from the wise, and have revealed them to little ones” (Matt. 11:25). Do you see that those whom the Son first humbled by word and example, upon whom the Holy Spirit then poured charity, the Father at last received in glory? The Son makes disciples, the Paraclete consoles friends, the Father exalts sons. And because not only the Son, but also the Father and the Holy Spirit are truly called Truth, it is clear that one and the same Truth, the property of the persons being kept, works these three things in the three steps. First, namely, He instructs, as a master; second, He consoles, as a friend or brother; third, He binds, as a father His sons.",
    "cap7-s21": "For the Son of God, namely the Word and Wisdom of the Father, first, when He finds that power of our soul which is called reason depressed by the flesh, captive to sin, blind with ignorance, given to outward things, taking it up mercifully, raising it powerfully, instructing it prudently, drawing it inward, and using it wonderfully as a deputy for Himself, sets it as a judge for itself, so that out of reverence for the Word to which it is joined, it, accuser, witness, and judge of itself, discharges the office of Truth against itself. From this first conjunction of the Word and reason, humility is born. Then the other part, which is called the will, infected indeed with the poison of the flesh, but already examined by reason, the Holy Spirit visiting it graciously, fighting sweetly, affecting it ardently, makes it merciful: so that after the manner of a hide, which when anointed is stretched, it too, poured through with a heavenly anointing, is dilated by affection even to enemies. And so from this second conjunction of the Spirit of God and the human will, charity is made. Then both parts, namely reason and will, the one instructed by the word of truth, the other breathed upon by the spirit of truth; the one sprinkled with the hyssop of humility, the other kindled with the fire of charity; the soul now perfect, without spot because of humility, without wrinkle because of charity; when neither the will resists reason, nor reason disguises the truth, the Father joins to Himself as a glorious spouse: so that neither reason is allowed to think of itself, nor the will of the neighbor, but that blessed soul delights to say only this: “The King has brought me into His chamber.” Worthy indeed, who from the school of humility, in which she first learned under the Master the Son to enter into herself, according to the threat made to her, “If you do not know yourself, go forth and feed your kids” (Song 1:3, 7); worthy, then, to be brought by affection from that school of humility, with the Holy Spirit as guide, into the cellars of charity (which are surely to be understood as the breasts of neighbors); whence, supported with flowers and surrounded with apples, that is with good manners and holy virtues, she may at last be admitted to the King’s chamber, for love of whom she languishes. There for a little while, for about half an hour, silence being made in heaven, resting sweetly among the desired embraces, she herself sleeps, but her heart watches, by which meanwhile she searches the secrets of truth: with the memory of which she may afterwards be fed when she returns to herself. There she sees invisible things, hears unspeakable things, which it is not lawful for a man to utter. They exceed all that knowledge which night indicates to night: yet day utters the word to day, and among the wise it is lawful to speak wisdom, and to the spiritual to compare spiritual things.",
    "cap8-title": "Chapter VIII. The same steps are declared in the rapture of Saint Paul.",
    "cap8-s22": "Do you think Paul had not passed these steps, who testifies that he was caught up as far as the third heaven? (2 Cor. 12:2.) But why “caught up,” and not rather “led”? Namely, so that if so great an Apostle says he was caught up, where he neither knew as one taught, nor could go as one led, I, who am beyond doubt less than Paul, may not presume that I can arrive at the third heaven by any virtue of mine, by any labor of mine: lest I either trust in virtue, or despair because of labor. For he who is taught or led is, by this very fact that he follows the one teaching or leading, shown to labor, and does something of himself, that he may be drawn to the destined place or meaning, so that he can say: “Yet not I, but the grace of God with me” (1 Cor. 15:10). But he who is caught up, leaning not on his own powers but on another’s, is carried he knows not where, and glories neither wholly in himself nor in part, where he works nothing either by himself or with another. To the first, then, or to the middle heaven the Apostle could ascend as one led or helped: but to reach the third he had to be caught up. For to this end the Son also is read to have descended, that He might call and help those who would ascend to the first; and the Holy Spirit to have been sent, who might lead to the second. But the Father, though He always cooperates with the Son and the Holy Spirit, is never read either to have descended from heaven or to have been sent to earth. I read indeed that “the earth is full of the mercy of the Lord” (Ps. 32:5); and, “Heaven and earth are full of Your glory,” and many such things. I read also of the Son, “When the fullness of time came, God sent His Son” (Gal. 4:4). And the Son Himself speaks of Himself, “The Spirit of the Lord has sent Me” (Isa. 61:1). And through the same prophet: “And now,” He says, “the Lord has sent Me, and His Spirit” (Isa. 48:16). I read also of the Holy Spirit, “But the Paraclete, the Holy Spirit, whom the Father will send in My name” (John 14:26); and, “When I have been taken up, I will send Him to you” (John 16:7), no doubt the Holy Spirit. But the Father in His own person, though He is nowhere not, I nowhere find except in the heavens, as in the Gospel, “And My Father who is in heaven” (Matt. 23:9); and in the prayer, “Our Father who art in heaven” (Matt. 6:9).",
    "cap8-s23": "From which I gather that because the Father did not descend, the Apostle, that he might see Him, could not indeed ascend to the third heaven, to which nevertheless he recorded that he was caught up. Finally, “No one has ascended into heaven except He who descended from heaven, the Son of Man” (John 3:13). And lest you think this said of the first or the second, David says to you: “His going forth is from the highest heaven” (Ps. 18:7). To which again He was not suddenly caught up, not secretly taken, but “while they looked on,” it says, that is the Apostles, “He was lifted up” (Acts 1:9). Not as Elijah, who had one (2 Kings 2); not as Paul, who had none (for he could scarcely have even himself as witness or umpire, himself declaring, “I know not, God knows”); but as the Almighty, who when He willed descended, when He willed ascended, awaiting according to His own choice witnesses and spectators, place and time, day and hour, “while they looked on,” whom namely He deigns with so great a vision, was lifted up. Paul was caught up, Elijah was caught up, Enoch was translated (Sir. 44:16): but our Redeemer is read to have been lifted up, that is, raised from Himself, not helped from elsewhere. Finally, not by the vehicle of a chariot, not by the aid of an angel, but supported by His own power, “a cloud received Him from their eyes” (Acts 1:9). Why this? Did it help one weary? Did it push one slow? Did it hold up one falling? Far from it. But it received Him from the carnal eyes of the disciples: who, though they had known Christ according to the flesh, should now know Him so no longer. Those, then, whom the Son calls through humility to the first heaven, the Spirit gathers in the second through charity, the Father exalts to the third through contemplation. First they are humbled in the truth, and say, “In Your truth You have humbled me” (Ps. 118:75). Second they rejoice with the truth, and sing, “Behold how good and how pleasant it is for brothers to dwell in one” (Ps. 132:1). For of charity it is written, “It rejoices with the truth” (1 Cor. 13:6). Third they are caught up to the secrets of truth, and say, “My secret to me, my secret to me” (Isa. 24:16).",
    "cap9-title": "Chapter IX. The groans and sighs of Saint Bernard, panting toward the Truth.",
    "cap9-s24": "But why do I, a wretch, with superfluous talkativeness more than with liveliness of spirit, run through the two higher heavens, who still labor under the lower, creeping on hands and feet? To which nevertheless already, with Him helping by whom I am also called, I have raised a ladder for myself. For there is the way by which He may show me the salvation of God. Already I look up to the Lord leaning from above, already I exult at the voice of truth. He called me, and I answered Him: “You will stretch out Your right hand to the work of Your hands” (Job 14:15). You indeed, O Lord, number my steps, but I, a slow climber, a weary traveler, look for byways. Woe to me, if darkness overtake me, or if my flight be in winter, or on the Sabbath: while now, when it is the acceptable time and the day of salvation, I put off setting out toward the light. Why do I delay? Pray for me, son, brother, companion, and sharer of my progress, if there is any, in the Lord. Pray the Almighty, that He may so strengthen the sluggish foot that yet the foot of pride may not come to me. For though a sluggish foot is not fit to climb the step of truth, it is still more tolerable than that which cannot stand in it, as you have there: “They were cast out, and could not stand” (Ps. 35:12–13).",
    "cap9-s25": "And this indeed of the proud. But what of their head? What of him who is called king over all the children of pride? (Job 41:25.) “And he,” it says, “did not stand in the truth” (John 8:44); and elsewhere, “I saw Satan like lightning falling from heaven” (Luke 10:18). Why this, if not because of pride? Woe to me, if He also who knows high things from afar should see me prideful, and thunder upon me that terrible voice: “You were indeed a son of the Most High, but you shall die like a man, and fall like one of the princes” (Ps. 81:6–7). Who would not fear at the voice of this thunder? O how much more healthfully did Jacob’s sinew of the thigh wither at the angel’s touch (Gen. 32:25), than did that of the proud angel swell, vanish, and fall. Would that an angel might touch my sinew also, that it may wither, if perhaps from this infirmity I may begin to advance, who from my own firmness can only fail. I read indeed: “The weakness of God is stronger than men” (1 Cor. 1:25). So also the Apostle, complaining of his own sinew, which an angel not of the Lord but of Satan was buffeting, heard the answer: “My grace is sufficient for you; for power is made perfect in infirmity.” What power? Let the Apostle himself answer: “Gladly will I glory in my infirmities, that the power of Christ may dwell in me” (2 Cor. 12:9). But perhaps you do not yet understand of which He spoke especially, because Christ had all the virtues. But though He had them all, yet above all He commended to us in Himself one, that is humility, when He said: “Learn from Me, for I am meek and humble of heart” (Matt. 11:29).",
    "cap9-s26": "Gladly therefore I also, Lord Jesus, will glory, if I can, in my infirmity, in the shrinking of my sinew, that Your power, that is humility, may be perfected in me. For Your grace is sufficient for me, when my own power has failed. Setting the foot of grace firmly, and gently drawing mine which is weak, I will climb securely by the ladder of humility: until, clinging to the truth, I pass over to the breadth of charity. Then I will sing with thanksgiving, and say: “You have set my feet in a spacious place” (Ps. 30:9). So a narrow way is more cautiously walked strictly, so a steep ladder is more safely climbed step by step; so in a wondrous manner, though more slowly, one climbs more firmly to the truth by limping. But woe is me, because my sojourning is prolonged! (Ps. 119:5.) Who will give me wings like a dove, with which I may fly more quickly to the truth, that I may already rest in charity? (Ps. 54:7.) And since they are lacking, lead me, O Lord, in Your way, and I will enter into Your truth, and the truth will set me free. Woe to me that I descended from it. For unless I had first descended lightly, emptily, I would not have labored so long, so heavily, in climbing. But why do I say, “I descended”? For perhaps I would more rightly have said, “I fell.” Except that, as no one suddenly becomes the highest, but each climbs by steps, so no one suddenly becomes the worst, but descends little by little. Otherwise how will that stand: “The wicked man is proud all the days of his life”? (Job 15:20.) Finally there are ways that seem good to men, and yet lead to evil.",
    "cap9-s27": "There is therefore a way of descent, as of ascent. And there is a way to good, and a way to evil. Beware the evil, choose the good. If you cannot of yourself, pray with the prophet, and say: “Remove from me the way of iniquity.” How? “And of Your law have mercy on me”; that law, namely, which You gave to those who go astray in the way, that is who abandon the truth, of whom I am one, who truly fell from the truth. But shall he who falls not add that he may rise again? For this I have chosen the way of truth, by which I may climb, humbled, from where I descended by pride. I will climb, I say, and I will sing: “It is good for me, O Lord, that You have humbled me; the law of Your mouth is good to me above thousands of gold and silver” (Ps. 118:29, 30, 71, 72). David seems to have set two ways before you, but you should know they are one; yet diverse from itself, and called by diverse names, either of iniquity because of those descending, or of truth because of those ascending: because the same steps belong to those climbing to a throne and to those descending; and the same way to those approaching a city and to those departing; and one door is of those entering a house and of those going out. Finally, by one ladder the angels appeared to Jacob, ascending and descending (Gen. 28:12). To what do these things look? Namely, that if you desire to return to the truth, it is not necessary to seek a new way which you do not know, but the known way by which you descended: so that, following your own footprints with reciprocal steps, you may climb by the same steps, humbled, by which you had descended in pride: so that what was the twelfth of pride for the one descending may be the first of humility for the one ascending; the eleventh is found the second; the tenth, the third; the ninth, the fourth; the eighth, the fifth; the seventh, the sixth; the sixth, the seventh; the fifth, the eighth; the fourth, the ninth; the third, the tenth; the second, the eleventh; the first, the twelfth. When these steps of pride have been found in you, or rather recognized, you no longer labor in seeking the way of humility.",
    "cap10-title": "Chapter X. On the first step of pride, which is curiosity.",
    "cap10-s28": "The first step of pride, then, is curiosity. You will detect it by such signs as these. If you see a monk, of whom you formerly had good confidence, wherever he stands, walks, sits, beginning to wander with his eyes, his head erect, carrying his ears cocked: from the motions of the outward man you may recognize that the inward has been changed. For a perverse man winks with the eye, scrapes with the foot, speaks with the finger (Prov. 6:12–13); and from the insolent motion of the body a recent disease of the soul is detected: which, while by carelessness of itself it grows sluggish in watching itself, makes it curious toward others. For because it does not know itself, it is sent outside to feed the kids (Song 1:7). Kids, which signify sin, I would rightly call the eyes and ears: because as death entered the world through sin, so through these windows it enters the mind. In feeding these, then, the curious man occupies himself, while he does not care to know what he has left within. And truly, if you attended to yourself vigilantly, O man, it is a wonder if you would ever attend to anything else. Hear, O curious one, Solomon; hear, O fool, the Wise Man. “With all watchfulness,” he says, “keep your heart” (Prov. 4:23): that all your senses may watch over that from which life proceeds. For whither, O curious one, do you withdraw from yourself? To whom do you meanwhile commit yourself? Why do you dare to lift your eyes to heaven, you who have sinned against heaven? Look upon the earth, that you may know yourself. It will represent you to yourself, because you are earth, and to earth you will go.",
    "cap10-s29": "Yet for two reasons you lift your eyes blamelessly, either to ask help or to give it. David lifted his eyes to the mountains, that he might ask (Ps. 120:1): and the Lord lifted His over the crowds, that He might give (John 6:5). The one miserably, the other mercifully, both blamelessly. You too, if considering place, time, and cause, you lift your eyes for your own need or your brother’s, I not only do not blame, but even greatly praise. For misery excuses the one, mercy commends the other. Otherwise I would call you an imitator not of the Prophet, not of the Lord, but of Dinah or of Eve, or rather of Satan himself. For Dinah, while she goes out to feed the kids, her virginity is taken from her father, and her own from herself (Gen. 34:1–2). O Dinah, what need is there that you see the women of another people? By what necessity? By what usefulness? Or by curiosity alone? Even if you look idly, you are not idly looked at. You gaze curiously, but you are gazed at more curiously. Who would then have believed that that curious idleness of yours, or idle curiosity, would afterwards be so not idle, but so pernicious to you, to yours, and to your enemies?",
    "cap10-s30": "You too, O Eve, were placed in paradise, that you might work with your husband and keep it: if you fulfill what was enjoined, to pass over at some time to something better, where there will be no need for you to be occupied in any work, nor to be anxious about custody. Every tree of paradise is granted you for eating, except that which is called of the knowledge of good and evil (Gen. 2:15–17). For if the rest are good, and taste of good, what need is there to eat of the tree which tastes also of evil? “Not to be wiser than it is fitting to be wise” (Rom. 12:3). For to taste evil is not to be wise, but to be foolish. Keep therefore what was committed, wait for what was promised; beware what was forbidden, lest you lose what was granted. Why do you gaze so intently on your own death? Why do you cast wandering lights so often there? Why does it please you to look at what it is not lawful to eat? “I stretch out my eyes,” you say, “not my hand. It is not forbidden that I see, but that I eat. May I not lift my eyes where I will, which God placed in my power?” To which the Apostle: “All things are lawful to me, but not all things are expedient” (1 Cor. 6:12). Even if it is not a fault, it is nevertheless a sign of a fault. For unless the mind kept itself less curiously, your curiosity would not have empty time. Even if it is not a fault, it is nevertheless an occasion of a fault, and a sign of one committed, and a cause of one to be committed. For while you are intent on something else, the serpent meanwhile secretly glides into your heart, addresses you blandly. He checks reason with blandishments, fear with lies. “By no means,” he says, “shall you die” (Gen. 3:4). He increases care, while he incites the gullet: he sharpens curiosity, while he suggests desire. At last he offers what was forbidden, and takes away what was granted: he holds out the apple, and snatches paradise. You drink the poison, about to perish, and about to bear those who will perish. Salvation perishes, birth does not cease. We are born, we die: and therefore we are born to die, because we first die about to be born. Therefore a heavy yoke is upon all your children even to this day.",
    "cap10-s31": "But you also, O seal of likeness, were placed not in paradise, but in the delights of the paradise of God (Ezek. 28:12–13). What more ought you to seek? Full therefore of wisdom, and perfect in beauty, seek not things higher than yourself, and search not things stronger than yourself. Stand in yourself, lest you fall from yourself, if you walk in great things and in wonders above yourself. But why do you meanwhile look aslant toward the north? Already I see you, already I perceive you searching I know not what high things above yourself more curiously. “I will set,” he says, “my seat toward the north” (Isa. 14:13). While the other heavenly citizens stand by, you alone affect to sit, and you attack the concord of the brothers, the peace of the whole heavenly country, and, as far as in you lies, the quiet of the Trinity itself. Whither does your curiosity, wretch, lead you, that by a singular presumption you do not hesitate to make scandal for the citizens, injury to the King? Thousands of thousands minister to Him, and ten times a hundred thousand stand before Him (Dan. 7:10), where no one is said to sit except He alone who sits above the Cherubim, to whom the rest minister: and you, looking more distinctly than the rest I know not at what, inquiring more curiously, invading more irreverently, set a seat for yourself in heaven, that you may be like the Most High? With what end? With what confidence? Measure, O fool, your strength, weigh the end, think out the measure. Do you presume this with the Most High knowing, or not knowing? willing, or not willing? But how can He either will, or be ignorant of, whatever evil you devise, whose will is best, whose knowledge is perfect? Or do you not doubt that He both knows and is unwilling, but think He cannot resist? Yet unless you doubt that you were created, I would not believe you doubt the omnipotence, or the complete knowledge and goodness of the Creator, who could from nothing, knew how to make you such, willed to make you so great. How then do you suppose God consents to what He does not will to be done, and can refuse? Or perhaps I see fulfilled in you, or rather begun by you, what after you, and through you by those like you on earth, is commonly said: “A private lord nourishes rash men”? Or is your eye evil, because He is good? From whose goodness, while you take a wicked confidence, you have been made both shameless against knowledge and bold against power.",
    "cap10-s32": "For this, O impious one, this is what you think; this is the iniquity which you meditate on your bed, and you say: “Do you think the Creator will destroy His own work? I know indeed that no thought of mine, of whatever kind, is hidden from God: for He is God. Nor does such a thought of mine please Him, because He is good. But neither, if He should will, would I escape His hand, because He is powerful. Yet is it to be feared by me? For if, since He is good, my evil cannot please Him, how much less His own? Mine, indeed, I would call the willing of something against His will: His, if He should avenge Himself. Therefore whatever crime He cannot will to avenge, as He neither wills nor can be deprived of His own goodness. You deceive yourself, wretch, you deceive yourself, not God. You, I say, deceive yourself, and iniquity lies to itself, not to God. You act indeed deceitfully, but in His sight. You therefore deceive yourself, not God. And because from His great good toward you you devise a great evil against Him, rightly is your iniquity found unto hatred. For what greater iniquity, than that the Creator should be despised by you for that very thing for which He deserved to be more loved? What greater iniquity, than that, while you do not doubt of the power of God—that He who could create can destroy you—yet, trusting in His great sweetness, by which you hope He is unwilling to avenge though He can, you repay evils for goods, hatred for love?",
    "cap10-s33": "This iniquity, I say, is not a momentary anger, but worthy of everlasting hatred, by which you desire and hope to be equaled to your most sweet and most high Lord, though against His will, so that He may always see what grieves Him, while He has you as a companion when He does not will, and does not cast you down when He can; that He would rather choose to grieve Himself than suffer you to perish; He could indeed cast down if He willed, but, as you suppose, because of sweetness He could not will. Surely if He is such as you think, you act so much the more wickedly if you do not love. And if He suffers something to be done against Himself rather than Himself do something against you: what great malice is it, that you should not even spare Him who does not spare Himself in sparing you? Yet far be it from His perfection that, because He is sweet, He should not be just, as if He could not be at once sweet and just: since a just sweetness is better than a remiss one; rather, sweetness without justice is not a virtue. Because therefore you are ungrateful to the free goodness of God, by which you were made freely, and you do not fear the justice which you have not experienced; and so you boldly commit a fault for which you falsely promise yourself impunity: now behold, you shall feel as just Him whom you knew as good, falling into the pit which you prepare for the Author: so that while you devise against Him a punishment which He can yet be without if He wills, but, as you think, cannot will to be without, and therefore cannot be without that goodness by which you have never found Him to have punished anyone: such a punishment let the just God most justly turn back upon you, who neither can nor ought to suffer His goodness to be offended with impunity: so tempering the sentence in vengeance that, if you will to come to your senses, He does not deny pardon; yet according to your hardness and impenitent heart you cannot will, and therefore cannot be without the punishment.",
    "cap10-s34": "But now hear the claim: “Heaven,” He says, “is My seat, and the earth the footstool of My feet” (Isa. 66:1). He did not say, East, or West, or some one region of heaven: but, “The whole heaven is My seat.” You cannot therefore sit in a part of heaven, when He has chosen the whole for Himself. On earth you cannot, because it is the footstool of His feet. For earth is a solid place, where the Church sits, founded upon a firm rock. What will you do? Driven from heaven, you cannot remain on earth. Choose therefore for yourself a place in the air, not for sitting, but for flying: so that you who tried to shake the state of eternity may feel the punishment of your own fluctuation. While you then fluctuate between heaven and earth, the Lord sits upon a throne high and lifted up, and the whole earth is full of His majesty (Isa. 6:3), so that nowhere except in the air may you find a place.",
    "cap10-s35": "For the Seraphim, flying with some wings of their contemplation from the throne to the footstool, from the footstool to the throne, and covering with others the head of the Lord and His feet, I suppose are placed there for this, that as for the sinning man entrance to paradise is forbidden by the Cherubim, so by the Seraphim a limit may be set to your curiosity: so that you may neither search the secrets of heaven now more shamelessly than prudently, nor know the mysteries of the Church on earth; but be content only with the hearts of the proud, who neither deign to be on earth like the rest of men, nor fly to heaven like the angels. Though the head in heaven and the feet on earth are hidden from you, yet something in the middle is permitted you to see, only that you may envy: while, suspended in the air, you look upon the angels descending through you and ascending; but what they either hear in heaven or announce on earth, you wholly do not know.",
    "cap10-s36": "O Lucifer, who rose in the morning, or rather no longer Lucifer, but night-bearer, or even death-bearer, your course was straight from the east to the south, and you in a reversed order tend to the north? The more you hasten to the heights, the more swiftly you decline to the setting. Yet I would inquire more curiously, O curious one, into the intention of your curiosity. “I will set,” he says, “my seat toward the north” (Isa. 14:13). I do not understand this north as bodily, nor this seat (since you are a spirit) as material. But I think that by the north reprobate men were designated; by the seat, power over them. Whom, in the foreknowledge of God, as much the nearer to Him, so much the more clear-sighted than the rest, seeing in advance, shining with no ray of wisdom, burning with no love of the spirit, you found as it were an empty place, and affected dominion over those whom you would pour through with a certain brightness of your cunning, inflame with the heats of your malice: so that as the Most High by His wisdom and goodness ruled all the children of obedience, so you also, made king over all the children of pride, might rule them by your cunning malice and malicious cunning, by which you would be like the Most High. But I wonder, when in the presence of God you foresaw your principality, why you did not in the same foresight foresee also your downfall. For if you foresaw it, what madness was it, that you should desire to rule with so great misery, that you should prefer to be over others miserably rather than to be under happily? Or was it not more expedient to be a partaker of those luminous plagues than a prince of these darknesses? But it is more credible that you did not foresee: either for that cause which I said above, because attending to the goodness of God you said in your heart, “He will not require it” (Ps. 10:13), for which, O impious one, you provoked God; or because, the principality being seen, at once a beam grew in the eye of pride, and with it interposed you could not see the fall.",
    "cap10-s37": "So Joseph, when he had foreseen his exaltation (Gen. 37:7–9), yet did not foresee his being sold, although the selling was nearer than the exaltation. Not that I would believe so great a patriarch fell into pride: but that by his example it may be clear that those who foresee future things by the spirit of prophecy, even if not all things, are not therefore to be thought to have foreseen nothing. But if anyone contends that vanity can be noted in this, that while still a youth he told his dreams, whose mystery he then did not know, I rather judge it to be ascribed to the mystery or to the simplicity of the boy than to vanity. Which yet, if there was any, could be expiated by the things he is read to have suffered. For to some, joyful things about themselves are sometimes shown by revelation, which, even if the human mind cannot know them without some vanity, what was shown will not therefore fail to come to pass; yet in such a way that that vanity is not unpunished, by which it even lightly exulted in itself at the greatness of the revelation or promise. For as a physician uses not only ointment but fire and iron, that he may cut and burn whatever has grown superfluous in healing a wound, lest it hinder the health which proceeds from the ointment: so God, the physician of souls, procures temptations for such a soul, sends tribulations, by which, afflicted and humbled, it may turn joy into mourning, and think the revelation an illusion. Whence it comes about that it is without vanity, and the truth of the revelation does not perish. So Paul’s elation is checked by the goads of the flesh (2 Cor. 12:7), and he himself is lifted by frequent revelations. So Zechariah’s unbelief is punished by the binding of the tongue (Luke 1:20), and the angel’s truth, to be manifested in its time, is not changed. So through glory and ignominy the saints advance, while among the singular gifts they receive they feel themselves struck by the common vanity of men: so that while by grace they discern something above themselves, they may not forget what they are.",
    "cap10-s38": "But what have revelations to do with curiosity? From which, that I might mix these things in by a digression, occasion was taken when I wished to show that the reprobate angel, before his fall, could so have foreseen that dominion over reprobate men which he afterwards received, as yet not to have foreknown his own damnation. Of which, some little questions having been raised rather than solved, this is the sum of the whole little discussion: that he fell from the truth through curiosity, because he first looked curiously at what he affected unlawfully and hoped presumptuously. Rightly therefore among the steps of pride curiosity claims the first for itself, which has also been found to be the beginning of every sin. But unless this is quickly checked, it soon slips into lightness of mind, which is the second step.",
    "cap11-title": "Chapter XI. On the second step of pride, which is lightness of mind.",
    "cap11-s39": "For a monk who, neglecting himself, looks curiously at others, while he looks up to some as superiors and looks down on some as inferiors, sees in some what he envies, in others what he mocks. Hence it comes that the mind, made light by the mobility of the eyes, in no way weighed down by care of itself, now by pride raises itself to the heights, now by envy sinks itself to the depths: now by envy it wastes away wickedly, now by excellence it grows merry childishly. In the one it is wicked, in the other vain, in both proud: because both what it grieves to be surpassed in, and what it rejoices to surpass, the love of its own excellence causes. And these vicissitudes of mind are indicated by words, now few and biting, now many and empty; now full of laughter, now of mourning, but always irrational. Compare, if you will, these first two steps of pride with the last two of humility: and see whether curiosity is not checked in the last, lightness in the last but one. You will find the same in the rest, if they are compared with one another. But now let us come to the third by teaching, not by descending.",
    "cap12-title": "Chapter XII. On the third step of pride, which is unseemly merriment.",
    "cap12-s40": "It is proper to the proud always to seek glad things and to avoid sad ones, according to that: “The heart of fools is where there is merriment” (Eccl. 7:5). Whence also the monk who has already descended two steps of pride, when through curiosity he has come to lightness of mind, when he sees the joy which he always seeks frequently interrupted by sadness, which he contracts from another’s goods, impatient of his own humiliation, flees to the counsel of a false consolation. From that side, then, on which his own cheapness and another’s excellence are shown, he restricts curiosity, that he may transfer himself wholly to the contrary side: so that he may more curiously note that in which he himself seems to excel; and always disguise that in which another excels: so that, while he avoids what is thought sad, merriment may be continued. And so it comes about that he whom joy and sadness claimed in turn begins to be possessed by unseemly merriment alone. In this, in which I have set the third step for you, receive by what signs you may detect it either in yourself or in another. Him who is of this sort you will hear groaning never, or rarely, or see weeping. You would think, if you attended, that he had either forgotten himself, or been washed from faults. Buffoonery appears in his signs, cheerfulness in his forehead, vanity in his gait. Prone to a joke, easy and ready in laughter. For all the things he knew in himself to be contemptible, and therefore sad, having been scraped from memory, and the good things, if he feels any in himself, gathered or feigned before the eyes of the mind, while he thinks of nothing except what pleases, and does not attend whether it is lawful, he can no longer hold laughter, no longer disguise unseemly merriment. For as a bladder swollen with collected wind, and pierced with a small puncture, if it is squeezed, crackles while it is deflated, and the wind going out, not poured everywhere but emitted narrowly, returns certain frequent sounds: so a monk, when he has filled his heart with vain and scurrilous thoughts, because of the discipline of silence not finding where the wind of vanity with which he is full may go out more fully, is shaken out through the narrows of the throat in giggles. Often he hides his face ashamed, closes his lips, clenches his teeth; he laughs unwilling, giggles against his will. And when he has blocked his mouth with his fists, he is still heard to sneeze through the nostrils.",
    "cap13-title": "Chapter XIII. On the fourth step of pride, which is boasting.",
    "cap13-s41": "But after vanity has begun to grow, and the bladder to swell, it is necessary that the windiness be belched through a wider hole, the fold being loosened, otherwise it will burst. So a monk, unseemly merriment overflowing, when he does not suffice to open it by laughter or signs, breaks out into the words of Elihu: “Behold my belly is as new wine without a vent, which bursts new bottles” (Job 32:19). He will therefore either speak, or burst. For he is full of words, and the spirit of his belly constrains him. He hungers and thirsts for hearers, to whom he may boast his vanities, to whom he may pour out all that he feels: to whom it may become known of what sort and how great he is. And when an occasion of speaking has been found, if the talk arises about letters, old things are brought forth, and new; sentences fly, swollen words resound. He anticipates the one asking, he answers the one not seeking. He himself asks, he himself solves, and he cuts off the imperfect words of his collocutor. But when, the signal having been struck, it is necessary that the conversation be interrupted, he complains of a long hour, a short interval; he seeks leave to return to fables after the hour, not that he may edify anyone, but that he may boast knowledge. He can edify, but he does not intend to edify. He does not care to teach you, or to be taught by you what he does not know; but that it may be known that he knows what he knows. And if religion is treated of, at once visions and dreams are brought forth. Finally he praises fasts, commends vigils, exalts prayers above all; he disputes most fully, but most vainly, about patience, about humility, and about each of the virtues: so that you, if you hear, may say that out of the abundance of the heart the mouth speaks, and that a good man brings forth good things from his good treasure (Luke 6:45). If the talk is turned to sports, in these the more accustomed he is, the more talkative he is found. You would say, if you heard, that his mouth, a stream of vanity, is a river of scurrility, so that it stirs even severe and grave minds to the lightness of laughter. And that I may gather the whole in brief, note boasting in much speaking. In this you have the fourth step both described and named. Flee the thing, and keep the name. With this same caution now approach the fifth, which I name singularity.",
    "cap14-title": "Chapter XIV. On the fifth step of pride, which is called singularity.",
    "cap14-s42": "It is shameful for him who boasts himself above the rest, if he does not do something more than the rest, by which he may appear beyond the rest. Therefore what the common rule of the monastery, or the examples of the elders, urge, is not enough for him. Yet he does not strive to be better, but to be seen. He longs not to live better, but to be seen to live, so that he may say: “I am not as the rest of men” (Luke 18:11). He flatters himself more over one fast which he makes while the rest are dining, than if he had fasted seven days with the rest. One little private prayer seems to him more convenient than the whole psalmody of one night. At dinner he is accustomed frequently to cast his eyes over the tables, so that if he sees anyone eat less, he grieves to be beaten, and begins cruelly to withdraw from himself what he had foreseen should be granted as necessary for food, fearing more the loss of glory than the torment of hunger. If he has seen anyone thinner, anyone paler, he thinks himself cheap, he never rests. And because he cannot see his own face, what sort he offers to those looking on, looking at the hands and arms which he can, he feels his ribs, handles his shoulders and loins: so that according as he proves the members of his body either too little or sufficiently wasted, he may distinguish the paleness of his face and its color. In short, strenuous for all his own things, sluggish for common ones. He watches in bed, sleeps in choir: and when, while others are singing at vigils, he dozes the whole night, after vigils, while others rest in the cloister, he remains alone in the oratory: he hawks and coughs, and from a corner fills the ears of those sitting outside with groans and sighs. But when from these things which he does singularly but emptily his reputation has grown among the simpler, who indeed approve the works they see, but do not discern whence they proceed; while they call the wretch blessed, they lead him into error (Isa. 3:12).",
    "cap15-title": "Chapter XV. On the sixth step of pride, that is arrogance.",
    "cap15-s43": "He believes what he hears, he praises what he does, and he does not attend to what he intends. He forgets the intention while he embraces the opinion. And he who in every other matter believes himself more than others, about himself alone believes others more than himself: so that he no longer prefers his religion in word only, or by the mere display of works, but by the inmost affection of the heart believes himself holier than all: and whatever he has known to be praised in himself, he arrogantly ascribes not to the ignorance or goodwill of the praiser, but to his own merits. Whence after singularity, arrogance rightly claims the sixth step for itself. After this presumption is found, in which the seventh step is constituted.",
    "cap16-title": "Chapter XVI. On the seventh step of pride, which is presumption.",
    "cap16-s44": "For he who thinks himself to excel others, how should he not presume more of himself than of others? He sits first in assemblies, he answers first in councils: uncalled he approaches, unbidden he intrudes: he reorders what has been ordered, he remakes what has been done. Whatever he himself has not done or ordered, he thinks neither rightly done nor beautifully ordered. He judges those who judge, he prejudges those about to judge. If, when the time has come, he is not promoted to the priorate, he judges his abbot either envious or deceived. But if some middling obedience is enjoined on him, he is indignant, he scorns it, thinking that he who feels himself fit for greater things is not to be occupied with lesser. But he who has been accustomed so readily to thrust himself into all things more rashly than freely, it is impossible that he should not at some time err. And it belongs to the prelate to rebuke the one erring. But how will he confess his fault, who neither thinks it is, nor suffers himself to be thought blameable? Therefore when a fault is imputed to him, it grows, it is not cut off. If then when he has been rebuked you see his heart decline into words of malice, know that he has fallen into the eighth step, which is called defense of sins.",
    "cap17-title": "Chapter XVII. On the eighth step of pride, which is defense of sins.",
    "cap17-s45": "Now excuses in sins are made in many ways. For either he who excuses himself says, “I did not do it”; or, “I did it, but I did well”; or, “If badly, not very badly”; or, “If very badly, not with a bad intention.” And if he is convicted even of that, like Adam or Eve, he tries to excuse himself by another’s persuasion. But he who shamelessly defends even open things, when would he humbly reveal to the abbot the hidden and evil thoughts coming to his heart?",
    "cap18-title": "Chapter XVIII. On the ninth step of pride, which is feigned confession.",
    "cap18-s46": "And though these kinds of excuse are judged evil to this extent, that they are called by the prophetic mouth words of malice (Ps. 140:4); yet far more dangerous is a false and proud confession than a stubborn and obstinate defense. For some, when they are rebuked for more open things, knowing that if they defended themselves they would not be believed, find a subtler argument of defense, answering with words of a deceitful confession. For there is, as it is written, one who wickedly humbles himself, and his inward parts are full of deceit (Sir. 19:23). The face is cast down, the body is prostrated: they wring out some little tears for themselves, if they can; they interrupt the voice with sighs, the words with groans. And not only does one of this sort not excuse what is objected, but he himself also exaggerates the fault: so that when you hear something impossible or incredible added to his fault by his own mouth, you may disbelieve even that which you thought established; and from that which you do not doubt is false while he confesses, that which was held as almost certain may come into doubt. And while they affirm what they do not wish to be believed, by confessing they defend the fault, and by opening they cover it; so that the confession sounds praiseworthily in the mouth, and iniquity is still hidden in the heart: so that he who hears may think them to confess more from humility than from truth, applying to them that of Scripture: “The just man is the accuser of himself in the beginning of his speech” (Prov. 18:17). For they prefer to be in peril among men as to truth rather than as to humility, while before God they are in peril on both sides. Or if the fault is so manifest that no cunning can cover it; nevertheless they assume the voice, not the heart, of one penitent, that they may wipe out the mark, not the fault, while they compensate the ignorance of an open transgression with the decoration of a public confession.",
    "cap18-s47": "Glorious is humility, with which even pride itself desires to cloak itself, lest it become cheap! But this tergiversation is quickly detected by the prelate, if he is not lightly bent to this proud humility, by which the more he disguises the fault, or puts off the punishment. The furnace proves the vessels of the potter, and tribulation discerns those truly penitent. For he who truly repents does not shrink from the labor of penitence: but whatever is enjoined on him for the fault which he hates, he embraces patiently with a silent conscience. In that obedience also, when hard and contrary things arise, and whatever injuries are inflicted, he does not grow weary in bearing, so as to show that he stands in the fourth step of humility. But he whose confession is feigned, when asked with one or a light insult, or a small punishment, can no longer feign humility, no longer disguise the feigning. He murmurs, he gnashes, he is angry; and he is proved not to stand in the fourth of humility, but to have fallen into the ninth step of pride, which, according as it has been described, can rightly be called feigned confession. How great do you think is then the confusion in the heart of the proud man, when the fraud is detected, peace is lost, praise is lessened, and the fault is not washed away? At last he is noted by all, judged by all: and all are the more vehemently indignant, the more they see to be false whatever they had formerly thought of him. Then it is necessary for the prelate to think him the less to be spared, the more he would offend all if he spared one.",
    "cap19-title": "Chapter XIX. On the tenth step of pride, which is rebellion.",
    "cap19-s48": "Here, unless heavenly pity look upon him (which is very difficult for such), he may silently acquiesce in the judgments of all; made soon shameless and impudent, so much the worse as more despairingly he falls by rebellion into the tenth step: for whereas before, arrogantly in secret, he had despised the brothers, now openly disobedient he despises even the master.",
    "cap19-s49": "And it is to be known that all the steps which I have divided into twelve can be gathered into three only: so that in the six higher there is contempt of the brothers, in the four following contempt of the master, in the two that remain the contempt of God is completed. It is also to be noted that these two last steps of pride, which in climbing are also the first of humility, as they are to be climbed outside the congregation, so they cannot be descended in the congregation. And that they ought to be climbed before is openly given to be understood from this, that of the third step it is read in the Rule: “The third,” it says, “step is, that one for the love of God subject himself in all obedience to a greater.” (Rule 7.31.) If therefore in the third step subjection is placed, which beyond doubt takes place when a novice is first associated with the convent, it follows that the two former are already understood to have been passed. Finally, when a monk despises the concord of the brothers and the sentence of the master, what does he do further in the monastery, except make scandal?",
    "cap20-title": "Chapter XX. On the eleventh step of pride, which is liberty of sinning.",
    "cap20-s50": "After the tenth step, then, which has been called rebellion, one expelled or gone out from the monastery is at once received by the eleventh. And then he enters ways that seem good to men, whose end (unless perhaps God hedge them for him) will plunge him into the depth of hell, that is into contempt of God. For the impious, when he has come into the depth of evils, despises (Prov. 18:3). And the eleventh step can be called liberty of sinning, by which a monk, when he now neither sees a master whom he may fear, nor brothers whom he may revere, delights so much the more securely, as more freely, to fulfill his desires, from which in the monastery he was restrained as much by shame as by fear. But although he now fears neither the brothers nor the abbot, he has not yet wholly lost the fear of God. Reason, still faintly murmuring, sets this before the will, and not without some hesitation he first accomplishes unlawful things; but, like one who tries a ford, he enters the whirlpool of vices step by step, not at a run.",
    "cap21-title": "Chapter XXI. On the twelfth step of pride, which is the habit of sinning.",
    "cap21-s51": "But after, by the terrible judgment of God, impunity follows the first crimes, the pleasure experienced is gladly repeated, the repeated flatters. With concupiscence reviving, reason is lulled, habit binds. The wretch is drawn into the depth of evils, is delivered captive to the tyranny of vices, so that, swallowed in the gulf of carnal desires, forgetful of his own reason and of the fear of God, the fool says in his heart: “There is no God” (Ps. 13:1). Now he uses the pleasant indifferently for the lawful; now mind, hands, or feet are not forbidden from thinking, doing, seeking the unlawful: but whatever has come into the heart, into the mouth, to the hand, he devises, chatters, and works, malevolent, vain-speaking, criminal. As finally, when all these steps have been climbed, the just man, with a heart now eager and without labor by good habit, runs to life: so the impious, having descended the same, not governing himself by reason, not holding himself by the bridle of fear, for an evil use, hastens fearlessly to death. Those in the middle are they who are wearied, distressed: who now are tortured by fear of hell, now, delayed by former habit, labor in descending or ascending. Only the highest and the lowest run without hindrance and without labor. This one hastens to death, that one to life; the one more eager, the other more downhill. Charity makes that one eager, cupidity makes this one downhill. In the one love, in the other stupor, does not feel labor. In that one, finally, perfect charity, in this one consummated iniquity, casts out fear. To the one truth, to the other blindness, gives security. The twelfth step, then, can be called the habit of sinning, by which the fear of God is lost, contempt is incurred.",
    "cap22-title": "Chapter XXII. Whether and how one should pray for the desperate, and for those dead according to the soul.",
    "cap22-s52": "“For such a one already,” says the apostle John, “I do not say that anyone should pray” (1 John 5:16). But do you say, O Apostle, that anyone should despair? Rather let him groan who loves him. Let him not presume to pray, nor let him cease to weep. What is it that I say? Does any refuge of hope perhaps remain, where prayer finds no place? Hear one believing, hear one hoping, and yet not praying. “Lord,” she says, “if You had been here, my brother would not have died.” Great faith, by which she believed that the Lord’s presence could have forbidden death if He had been there. But now what? Far be it that she should doubt that He whom she believed could keep the living, can raise the dead. “But now,” she says, “I know that whatever You ask of God, God will give You.” Then to Him asking where they had laid him, she answers: “Come and see.” Why? O Martha, you give us great marks of your faith: but how, with so great a faith, do you distrust? “Come,” you say, “and see.” Why also, if you do not despair, do you not follow, and say, “And raise him”? If you do despair, why do you weary the Master without cause? Or does faith sometimes receive what prayer does not presume? Finally you forbid Him approaching the corpse, and say: “Lord, already he stinks; for he is four days dead” (John 11:21, 22, 34, 39). Do you say this despairing, or dissembling? For so the Lord Himself after the resurrection pretended that He would go farther (Luke 24:28), when He preferred to remain with the disciples. O holy women, familiars of Christ, if you love your brother, why do you not beg His mercy, of whose power you cannot doubt, of whose piety you cannot distrust? They answer: So we pray better as if not praying, so we trust more effectively as if distrusting. We show faith, we bear witness to affection: He knows, to whom it is not needful that anything be said, what we desire. We know indeed that He can do all things: but this so great a miracle, so new, so unheard of, even if it lies within His power, yet greatly exceeds all the merits of our humility. It is enough for us to have given a place to power, an occasion to piety; preferring patiently to wait for what He wills rather than shamelessly to seek what perhaps He does not will. Finally what our merits lack, shame perhaps will supply. In Peter also, after a heavy fall, I see a tear, but I do not hear a prayer: nor yet do I doubt of pardon.",
    "cap22-s53": "Learn also in the Mother of the Lord to have a great faith in wonders, to keep shame in a great faith. Learn by shame to adorn faith, to check presumption. “They have no wine,” she says (John 2:3). How briefly, how reverently she suggested that of which she was piously anxious! And that you may learn in such things rather to groan piously than to ask presumptuously; the shade of modesty tempering the heat of piety, she bashfully suppressed the conceived confidence of a prayer. She did not approach boldly, she did not speak openly, so as to say audaciously before all: “I beseech You, son, the wine fails, the guests are sad, the bridegroom is confounded; show what You can.” But though this, or much more, a burning breast, a fervent affection, would speak; yet privately the pious mother approached her powerful Son, not testing power, but exploring the will. “They have no wine,” she says. What more modest? What more faithful? Faith was not lacking to piety, gravity to the voice, efficacy to the wish. If then she, though she is mother, forgetting herself as mother, does not dare to ask the miracle of wine: I, a cheap servant, to whom it is a great thing to be a household servant of the Son and of the Mother together, with what face do I presume to ask life for one four days dead?",
    "cap22-s54": "Two also in the Gospel are read to have received sight, the one to have accepted it, the other to have recovered it: the one what he had lost, the other what he had never had; one namely blinded, the other born blind. But he who was blinded merited a wondrous mercy by miserable and wondrous cries: but he who was born blind felt no less, so much the more mercifully as more wondrously, the benefit of his enlightener, not anticipated by any prayers of his own. To the former, finally, it was said, “Your faith has saved you”: but not to this one (Luke 18:35–43; John 9). Two also recently dead, a third already four days, I read raised: yet only the daughter of the ruler of the synagogue, still placed in the house, by the prayers of her father; but the two from the unhoped-for greatness of piety (Mark 5:35–42; Luke 7:11–15; John 11).",
    "cap22-s55": "In a like form also, if it should happen (which God avert) that one of our brothers should die, not in body but in soul; so long as he is still among us, I also, such a sinner as I am, will knock, I will knock also with the prayers of the brothers upon the Savior. If he comes to life, we shall have gained a brother: but if we do not deserve to be heard, when he can no longer either bear the living or be borne by the living, but begins to be carried out, I always indeed groan faithfully, but I no longer pray so trustingly. I do not dare to say openly, “Come, Lord, raise our dead”: yet with a suspended heart I do not cease to cry within, trembling, “If perhaps, if perhaps, if perhaps the Lord will hear the desire of the poor, His ear will hear the preparation of their heart”; and that, “Will You do wonders for the dead, or shall physicians raise them, and they confess to You?” and of the four-days-dead: “Shall anyone tell Your mercy in the grave, and Your truth in destruction?” (Ps. 87:11–12.) The Savior can meanwhile, if He wills, meet us unhoped and unforeseen, and moved by the tears of those carrying, not by prayers, restore the life of the dead to the living, or even already buried call him back from the dead. And I would call him dead who, defending his own sins, has already fallen into the eighth step. For from the dead, as from one who is not, confession perishes (Sir. 17:26). But after the tenth, which is the third from the eighth, he is already carried out into the liberty of sinning, when he is expelled from the company of the monastery. And after he has passed the fourth, he is already rightly called four days dead, while falling into the fifth he is buried by habit.",
    "cap22-s56": "But far be it from us that even for such, though we do not presume openly, we should cease to pray even in our hearts: since Paul also mourned those whom he knew to have died without penitence (2 Cor. 12:21). For though they exclude themselves from common prayers, they cannot wholly from affections. Yet let them see in how great peril they are, for whom the Church does not dare to pray openly, who prays confidently even for Jews, for heretics, for Gentiles. For while on Good Friday prayer is made by name for any evils whatsoever, yet no mention is made of the excommunicated.",
    "cap22-s57": "You say perhaps, brother Godfrey, that I have at last exhibited something other than you asked, and than I myself promised, since instead of the steps of humility I seem to have described the steps of pride. To which I: I could not teach except what I have learned. I did not think it fitting that I should describe ascents, who know how to descend more than to ascend. Let blessed Benedict set before you the steps of humility, which he first arranged in his own heart: I have nothing to set forth except the order of my own descent. In which nevertheless, if it is diligently looked into, the way of ascent is perhaps found. For if a man coming from there met you as you were going to Rome, and being asked the way, what better could he show than that by which he came? While he names the castles, villages, cities, rivers, and mountains through which he has passed, announcing his own journey, he foretells yours to you: so that you recognize in going the same places which he passed through in coming. In this descent of ours likewise you will perhaps find the ascending steps, which in climbing you will read better in your own heart than in our book. Amen.",
}


def main() -> None:
    units = json.loads(LATIN.read_text(encoding="utf-8"))
    missing = []
    for u in units:
        eng = EN.get(u["id"])
        if not eng:
            missing.append(u["id"])
            eng = ""
        u["english"] = eng
        u["label"] = (
            u["heading"]
            if u["kind"] in {"title", "retractatio", "praefatio", "chapter-title"}
            else (f"{u['section']}" if u.get("section") else u["id"])
        )
    if missing:
        raise SystemExit(f"missing English for: {missing}")
    add_chunks(units)
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps(units, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    report(units)
    print(f"wrote {len(units)} units -> {OUT}")


if __name__ == "__main__":
    main()
